//import liraries
import React, {useEffect, useState} from 'react';
import {FlatList, ScrollView, useWindowDimensions, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {isNull} from 'lodash';
import TextCM from '../../../../components/Text';
import DateUtils from '../../../../../utils/DateUtils';
import {
  useQDTHAService,
  useReceiptServices,
} from '../../../../../hooks/apiHooks/useAPI';
import {IHistoryReceiptItem} from '../../../../../model/interface/receipt.interface';
import {IconHistoryDone} from '../../../../../assets/images';

type Props = {
  onClose: () => void;
  id: string;
};

const HistoryTicket = ({onClose, id}: Props) => {
  const {t} = useTranslation();
  const {height} = useWindowDimensions();
  const ReceiptService = useReceiptServices();
  const QDTHAServices = useQDTHAService();
  const [listHistories, setListHistories] = useState<IHistoryReceiptItem[]>([]);
  useEffect(() => {
    getTicketHistories();
  }, []);

  const getTicketHistories = async () => {
    try {
      const dataHistory = await QDTHAServices.getDetailMyDYCHistory(id);
      if (dataHistory) {
        setListHistories(dataHistory);
      } else {
        setListHistories([]);
      }
    } catch (error) {
      console.error(error);
    } finally {
    }
  };
  const renderItem = ({
    item,
    index,
  }: {
    item: IHistoryReceiptItem;
    index: number;
  }) => {
    return (
      <>
        {!isNull('item.createdBy') && (
          <>
            <View style={styles.ctnItem}>
              <View style={styles.ctnViewIcon}>
                <IconHistoryDone width={24} height={24} />
              </View>
              <View style={{rowGap: 4, flex: 1}}>
                <View>
                  <TextCM style={styles.title}>
                    {t(`BLDT.history.${item.status}`)}
                  </TextCM>
                </View>
                <View style={styles.ctnDes}>
                  <TextCM style={styles.Des}>
                    {`${DateUtils.convertDateToDDMMYYYY_H_M(
                      item.createdDate,
                    )} ${t('TK.by')} ${item.createdBy}`}
                  </TextCM>
                </View>
              </View>
            </View>
            {listHistories.length - 1 !== index && (
              <View style={styles.tabHoz}></View>
            )}
          </>
        )}
      </>
    );
  };

  return (
    <>
      <ScrollView
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        style={{maxHeight: (height / 3) * 2}}>
        <FlatList
          scrollEnabled={false}
          keyExtractor={item => item.id}
          data={listHistories?.reverse()}
          renderItem={renderItem}
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                flex: 1,
              }}>
              <TextCM>{t('CM.emptyData')}</TextCM>
            </View>
          )}
        />
      </ScrollView>
    </>
  );
};

export default HistoryTicket;
