import React, {useCallback, useEffect, useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {
  ActivityIndicator,
  FlatList,
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';

// import RenderTabView from './component/tab-view';
import {CalendarRange, Icon, IndexPath, Input} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import {styles} from './styles';
import {Color} from '../../../constants';

import {
  useCatalogService,
  useQDTHAService,
} from '../../../hooks/apiHooks/useAPI';

import useDebounce from '../../../hooks/useDebounce';
import TextCM from '../../components/Text';
import {useFocusEffect, useRoute} from '@react-navigation/native';
import LoadingMore from '../../components/LoadingMore';
import {DateUtils} from '../../../utils';
import {
  listPayment,
  listRequestStatusQDTHA,
  listSourceOfReceipt,
} from './component/modal-filter/helper';
import DYCItem from './component/DYC-item';
import ModalFilter from './component/modal-filter';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useAccountInfoServices} from '../../../hooks/apiHooks/useAccountInfoServices';
import {RequestData} from '../../../model/interface/qdtha.interface';
import {useConfigStore} from '../zustand/config';
import {useAppSelector} from '../../../hooks/useRedux';

export type ValueFilterSearchDYC = {
  type?: IndexPath[];
  rangeDay?: CalendarRange<Date>;
  requestStatus?: IndexPath[];
  paymentMethod?: IndexPath[];
  flowStatus?: IndexPath[];
  orgIn?: IndexPath;
};
const DYCScreen = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const CatalogService = useCatalogService();
  const AccountService = useAccountInfoServices();
  const {setListAPPLICATION_STATUS, LIST_APPLICATION_STATUS, LIST_ORG} =
    useConfigStore();
  const {dataAccount} = useAppSelector(state => state.account);

  const QDTHAServices = useQDTHAService();
  const isReload = route?.params?.isReload || false;
  const type = route?.params?.type;
  const [value, setValue] = useState('');
  const valueTextSearch = useDebounce(value, 300);
  const [visibleFilter, setVisibleFilter] = useState(false);

  const [valueFilterSearch, setValueFilterSearch] =
    useState<ValueFilterSearchDYC>();
  const [listMyDYC, setListMyDYC] = useState<RequestData[]>([]);
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [typereceipt] = useState([
    // {type: 'onsite', name: 'Yêu cầu trực tuyến'},
    {type: 'online', name: 'Yêu cầu trực tiếp'},
  ]);
  const [currentTypeReceipt, setCurrentTypeReceipt] = useState<
    'onsite' | 'online'
  >('online');

  const getListAppStatus = async () => {
    const data = await CatalogService.getAppStatus();
    if (data) {
      setListAPPLICATION_STATUS(
        data.map((d: any) => ({
          id: d.id,
          label: d?.['textField_input-1'],
          value: d?.['textField_input-2'],
          color: d?.['textField_input-3'],
          bgColor: d?.['textField_input-4'],
        })),
      );
    }
    return data;
  };

  useEffect(() => {
    if (!LIST_APPLICATION_STATUS.length) {
      getListAppStatus();
    }
    // AccountService.loginMiniApp();
  }, []);

  useFocusEffect(
    useCallback(() => {
      getDataDYC(0, false);
    }, [isReload, valueFilterSearch, valueTextSearch, currentTypeReceipt]),
  );

  const getDataDYC = async (page: number, isLoadMore?: boolean) => {
    try {
      if (isLoadMore) {
        setIsLoadMore(true);
      } else {
        setIsLoading(true);
      }
      const bodySearch: any = {
        advanced: false,
        q: valueTextSearch?.trim(),
        multiRange: [{field: 'requestDate', gte: null, lte: null}],
        terms: {},
      };
      if (type !== 'receiptOfMine') {
        if (!valueFilterSearch?.orgIn) {
          bodySearch.orgIn = dataAccount?.orgIn || '/561/978';
        } else {
          bodySearch.orgIn = LIST_ORG[valueFilterSearch?.orgIn?.row]?.orgIn;
        }
      }
      if (valueFilterSearch?.paymentMethod) {
        bodySearch.terms.paymentMethod = valueFilterSearch?.paymentMethod?.map(
          item => listPayment[item.row].value,
        );
      }
      if (valueFilterSearch?.flowStatus) {
        bodySearch.terms.flowStatus = valueFilterSearch?.flowStatus?.map(
          item => listRequestStatusQDTHA[item.row].value,
        );
      }
      if (valueFilterSearch?.type) {
        bodySearch.terms.type = valueFilterSearch?.type?.map(
          item => listSourceOfReceipt[item.row].value,
        );
      }
      if (valueFilterSearch?.requestStatus) {
        bodySearch.terms.requestStatus = valueFilterSearch?.requestStatus?.map(
          item => LIST_APPLICATION_STATUS[item.row].value,
        );
      }
      if (valueFilterSearch?.rangeDay?.startDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'createdDate',
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
            lte: null,
          };
        }
      }
      if (valueFilterSearch?.rangeDay?.endDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'createdDate',
            gte: null,
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        }
      }

      const res = await QDTHAServices.getMyDYC(
        page,
        20,
        bodySearch,
        type === 'receiptOfMine' ? 'owner' : 'authorized',
      );
      if (page === 0) {
        setListMyDYC(res?.data);
        setTotalPages(res?.totalData);
      } else {
        setListMyDYC([...listMyDYC, ...res?.data]);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
      setIsLoadMore(false);
      setIsFreshing(false);
    }
  };

  const handleSubmitFilter = () => {
    setVisibleFilter(false);
  };

  const checkIsFilter = () => {
    return (
      valueFilterSearch?.rangeDay?.endDate ||
      valueFilterSearch?.rangeDay?.startDate ||
      valueFilterSearch?.paymentMethod?.length ||
      valueFilterSearch?.flowStatus?.length ||
      valueFilterSearch?.type?.length
    );
  };

  const handleChangeTypeReceipt = (type: 'onsite' | 'online') => {
    setCurrentTypeReceipt(type);
  };

  const renderTypeReceipt = (item: any) => {
    return (
      <TouchableOpacity
        key={item.type}
        onPress={() => handleChangeTypeReceipt(item.type)}
        style={styles.containerTypereceipt}>
        {currentTypeReceipt === item.type ? (
          <View style={styles.typeReceiptSelected}>
            <View style={styles.typeReceiptSellectedIn}></View>
          </View>
        ) : (
          <View style={styles.typeReceiptDefault}></View>
        )}
        <TextCM
          style={[
            styles.textTypeReceipt,
            {
              color: currentTypeReceipt === item.type ? '#262D34' : '#667085',
            },
          ]}>
          {item.name}
        </TextCM>
      </TouchableOpacity>
    );
  };

  const onRefresh = () => {
    setIsFreshing(true);
    setPage(0);
    getDataDYC(0, false);
  };

  const handleLoadMore = () => {
    if (page < Math.ceil(totalPages / 20)) {
      getDataDYC(page + 1, true);
      setPage(page + 1);
    }
  };

  const getNumberFilter = () => {
    let count = 0;
    if (valueFilterSearch?.paymentMethod?.length) {
      count += 1;
    }
    if (valueFilterSearch?.flowStatus?.length) {
      count += 1;
    }
    if (valueFilterSearch?.type?.length) {
      count += 1;
    }
    if (valueFilterSearch?.requestStatus?.length) {
      count += 1;
    }
    if (
      valueFilterSearch?.rangeDay?.startDate ||
      valueFilterSearch?.rangeDay?.endDate
    ) {
      count += 1;
    }
    return count;
  };

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <SafeAreaView edges={['bottom']} style={styles.ctn}>
        <HeaderCM
          title={
            type == 'receiptOfMine'
              ? 'Đơn yêu cầu của tôi'
              : 'Đơn yêu cầu của tổ chức'
          }
          useLinearGradient={false}
          style={{backgroundColor: Color.QDTHACMColor}}
          contentStyle={{backgroundColor: Color.QDTHACMColor}}
        />
        <View style={styles.wrapInputSearch}>
          <Input
            allowFontScaling={false}
            style={styles.inputSearch}
            textStyle={{color: Color.Black}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('CM.search')}
            value={value}
            status="basic"
            onChangeText={setValue}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill={Color.Black} />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={styles.wrapFilterIcon}>
            <Icon
              fill={Color.White}
              name={checkIsFilter() ? 'funnel' : 'funnel-outline'}
              width={25}
              height={25}
            />
            <View style={styles.ctnFilter}>
              <TextCM style={styles.numbFilter}>{getNumberFilter()}</TextCM>
            </View>
          </TouchableOpacity>
        </View>

        <View style={{flexDirection: 'row', gap: 16, marginBottom: 10}}>
          {typereceipt.map((item: any) => renderTypeReceipt(item))}
        </View>

        {!isLoading && (
          <FlatList
            showsVerticalScrollIndicator={false}
            data={listMyDYC}
            keyExtractor={item => item?.id}
            renderItem={({item}) => <DYCItem dycItem={item} />}
            onEndReachedThreshold={0.5}
            onRefresh={onRefresh}
            refreshing={isRefreshing}
            onEndReached={handleLoadMore}
            ListEmptyComponent={() => (
              <View
                style={{
                  alignItems: 'center',
                  justifyContent: 'center',
                  flex: 1,
                }}>
                <TextCM>{t('CM.emptyData')}</TextCM>
              </View>
            )}
            contentContainerStyle={{rowGap: 16}}
            ListFooterComponent={() => isLoadMore && <LoadingMore />}
          />
        )}

        <BottomSheetCM
          title={t('CM.filter')}
          onClose={() => setVisibleFilter(false)}
          isVisible={visibleFilter}
          renderContent={
            <ModalFilter
              handleSubmitFilter={handleSubmitFilter}
              onClose={() => setVisibleFilter(false)}
              setValueFilterSearch={setValueFilterSearch}
              valueFilterSearch={valueFilterSearch}
              type={type === 'receiptOfMine' ? 'owner' : 'authorized'}
            />
          }
        />
      </SafeAreaView>
    </TouchableWithoutFeedback>
  );
};

export default DYCScreen;
